#include "NCLGLBuffer.h"
NCLGLBuffer::NCLGLBuffer() {
    W = 0;
    H = 0;
    length = 0;
}

void NCLGLBuffer::ini(std::string type, bool linear, std::string mode) {
    _type = std::string(type); // "FLOAT"|"FLOAT4"
    _supportFormat = GL_FLOAT;

    bool _linear = linear;
    _mode = std::string(mode); // "SAMPLER"|"ATTRIBUTE"|"VERTEX_INDEX"
    //printf("mode: %s\n", _mode.c_str());

    if(strcmp(_mode.c_str(), "SAMPLER")==0) {
        glGenTextures(1, &textureData);
        glGenTextures(1, &textureDataTemp);
    }
    if(strcmp(_mode.c_str(), "SAMPLER")==0 || strcmp(_mode.c_str(), "ATTRIBUTE")==0 || strcmp(_mode.c_str(), "VERTEX_INDEX")==0) {
        glGenBuffers(1, &vertexData0);
    }
    glGenFramebuffers(1, &fBuffer);
    glGenRenderbuffers(1, &renderBuffer);
    glGenFramebuffers(1, &fBufferTemp);
    glGenRenderbuffers(1, &renderBufferTemp);
};

/**
 * createFramebufferAndRenderbuffer
 */
void NCLGLBuffer::createFramebufferAndRenderbuffer() {
    //std::cout << renderBuffer << std::endl;
    glBindRenderbuffer(GL_RENDERBUFFER, renderBuffer);
    glRenderbufferStorage(GL_RENDERBUFFER, GL_DEPTH_COMPONENT32F, W, H);

    glBindFramebuffer(GL_FRAMEBUFFER, fBuffer);
    glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT, GL_RENDERBUFFER, renderBuffer);

    glBindFramebuffer(GL_FRAMEBUFFER, 0);


    //std::cout << renderBufferTemp << std::endl;
    glBindRenderbuffer(GL_RENDERBUFFER, renderBufferTemp);
    glRenderbufferStorage(GL_RENDERBUFFER, GL_DEPTH_COMPONENT32F, W, H);

    glBindFramebuffer(GL_FRAMEBUFFER, fBufferTemp);
    glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT, GL_RENDERBUFFER, renderBufferTemp);

    glBindRenderbuffer(GL_RENDERBUFFER, 0);
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
};

// WebGL2
// texImage2D(enum target, int level, int internalformat, sizei width, sizei height, int border, enum format, enum type, ArrayBufferView srcData, uint srcOffset)
// texImage2D(enum target, int level, int internalformat, sizei width, sizei height, int border, enum format, enum type, TexImageSource source);
// texImage2D(enum target, int level, int internalformat, sizei width, sizei height, int border, enum format, enum type, intptr offset);
void NCLGLBuffer::tp() {
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);

    /*glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR_MIPMAP_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    this._gl.generateMipmap(GL_TEXTURE_2D);*/
}
/**
 * Write WebGLTexture buffer
 * @param {Array<float>|Float32Array|Uint8Array|WebGLTexture|HTMLImageElement} arr
 * @param {boolean} [flip=false]
 */
void NCLGLBuffer::writeWebGLTextureBuffer(float * arr) {
    glBindTexture(GL_TEXTURE_2D, textureData);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA32F, W, H, 0, GL_RGBA, _supportFormat, arr);
    tp();

    glBindTexture(GL_TEXTURE_2D, textureDataTemp);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA32F, W, H, 0, GL_RGBA, _supportFormat, arr);
    tp();

    glBindTexture(GL_TEXTURE_2D, 0);
};

float * NCLGLBuffer::prepareArr(float * arr, float * arrD) {
    if(strcmp(_type.c_str(), "FLOAT4")==0) {
        for(int n=0; n < length*4; n++)
            arrD[n] = arr[n];
    } else if(strcmp(_type.c_str(), "FLOAT")==0) {
        for(int n=0; n < length; n++) {
            int idd = n*4;
            arrD[idd] = arr[n];
            arrD[idd+1] = 0.0;
            arrD[idd+2] = 0.0;
            arrD[idd+3] = 0.0;
        }
    }

    return arrD;
}
/**
 * Write on buffer
 * @param {Array<float>|Float32Array|Uint8Array|WebGLTexture|HTMLImageElement} arr
 * @param {boolean} [flip=false]
 * @param {Array<Float2>} [overrideDimensions=new Array(){Math.sqrt(value.length), Math.sqrt(value.length)}]
 */
void NCLGLBuffer::writeBuffer(float * arr, int valueLength, bool flip, float * overrideDimensions) {
    int vl = 0;

    if(length != 0) {
        #if DEBUG
            printf("deleting framebuffer/renderbuffer");
        #endif
        glDeleteFramebuffers(1, &fBuffer);
        glDeleteFramebuffers(1, &fBufferTemp);

        glDeleteRenderbuffers(1, &renderBuffer);
        glDeleteRenderbuffers(1, &renderBufferTemp);
    }

    if(overrideDimensions[0] != 0) {
        length = (int)overrideDimensions[0] * (int)overrideDimensions[1];
        vl = length*4;

        W = (int)overrideDimensions[0];
        H = (int)overrideDimensions[1];
    } else {
        length = ((strcmp(_type.c_str(), "FLOAT4")==0) ? valueLength/4 : valueLength);
        vl = valueLength;

        W = ceil(sqrt(length));
        H = W;
    }

    float * prepArr_ptr = (float*)malloc(sizeof(float)*(W*H*4));

    prepArr_ptr = (overrideDimensions[0] != 0) ? arr : prepareArr(arr, prepArr_ptr);

    #if DEBUG
        printf("\t[NCLGLBuffer writeBuffer] mode: %s, vl: %d, dims(%d %d) size(%d %d)\n", _mode.c_str(), vl, (int)overrideDimensions[0], (int)overrideDimensions[1], W, H);
    #endif

    if(strcmp(_mode.c_str(), "SAMPLER")==0) {
        //printf("texbuffer... \n");
        writeWebGLTextureBuffer(prepArr_ptr);
        //printf("texbuffer writed \n");
    }
    if(strcmp(_mode.c_str(), "SAMPLER")==0 || strcmp(_mode.c_str(), "ATTRIBUTE")==0) {
        //printf("vertexbuffer... \n");
        glBindBuffer(GL_ARRAY_BUFFER, vertexData0);
        glBufferData(GL_ARRAY_BUFFER, vl*sizeof(GLfloat), arr, GL_STATIC_DRAW);
        //printf("vertexbuffer writed \n");
    }

    createFramebufferAndRenderbuffer();
};

/**
 * Write on buffer
 * @param {Array<float>|Float32Array|Uint8Array|WebGLTexture|HTMLImageElement} arr
 * @param {boolean} [flip=false]
 * @param {Array<Float2>} [overrideDimensions=new Array(){Math.sqrt(value.length), Math.sqrt(value.length)}]
 */
void NCLGLBuffer::writeIndices(uint16_t * arr, int valueLength) {
    length = ((strcmp(_type.c_str(), "FLOAT4")==0) ? valueLength/4 : valueLength);

    if(strcmp(_mode.c_str(), "VERTEX_INDEX")==0) {
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, vertexData0);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, valueLength*sizeof(GLshort), arr, GL_STATIC_DRAW);
    }
};

/**
 * Remove this buffer
 */
void NCLGLBuffer::remove() {
    if(strcmp(_mode.c_str(), "SAMPLER")==0) {
        glDeleteTextures(1, &textureData);
        glDeleteTextures(1, &textureDataTemp);
    }

    if(strcmp(_mode.c_str(), "SAMPLER")==0 || strcmp(_mode.c_str(), "ATTRIBUTE")==0 || strcmp(_mode.c_str(), "VERTEX_INDEX")==0) {
        glDeleteBuffers(1, &vertexData0);
    }

    glDeleteFramebuffers(1, &fBuffer);
    glDeleteFramebuffers(1, &fBufferTemp);

    glDeleteRenderbuffers(1, &renderBuffer);
    glDeleteRenderbuffers(1, &renderBufferTemp);
};

NCLGLBuffer::~NCLGLBuffer (void) {

}